// Typed access to prices.json (generated by scripts/import-prices.mjs).
import data from "./prices.json";
import type { Locale } from ".";

export type Variant = { label: string; price: string };
export type PriceRow = {
  name: string;
  prices: string[];
  variants?: Variant[];
  unit?: string;
  from?: boolean;
  note?: string;
};
export type PriceCategory = { id: number; title: string; suspended: boolean; rows: PriceRow[] };

type LangData = { categories: PriceCategory[]; rules: { title: string; text: string } | null };
const byLang = data as unknown as Record<Locale, LangData>;

export const categoriesById = (lang: Locale, ids: number[]) =>
  ids.map((id) => byLang[lang].categories.find((c) => c.id === id)).filter((c): c is PriceCategory => !!c);

// The regulation only exists in Romanian on the source site.
export const rulesText = () => byLang.ro.rules?.text ?? "";
